#include <assert.h>
#include "save_store.h"
static void ready(Combat*g){g->sp=g->maxsp;g->castDelay=0;memset(g->skillCD,0,sizeof(g->skillCD));}
int main(){Combat g;combat_init(&g,1500,1500,NULL,NULL);g.level=20;g.jobId=4;g.joblevel=20;g.ranks[8]=10;g.skillPoints=9;g.statPoints=stat_budget(20);stat_refresh(&g);g.hp=g.maxhp;g.equipment=1;memset(g.mobs,0,sizeof(g.mobs));g.peaceful=1;CombatMob*m=&g.mobs[0];m->enabled=1;m->kind=2;m->x=g.x+8;m->y=g.y;m->spawnDef=-1;unsigned doubles=0,crits=0;for(int k=0;k<2000;k++){m->hp=100000;g.cooldown=0;g.autoAttack=1;g.target=0;unsigned n=g.damageNext;combat_tick(&g,.05,0,0);assert(g.damageNext==n+1);DamageEvent*d=&g.damage[(g.damageNext-1)%DAMAGE_EVENTS];assert(d->value==100000-m->hp&&d->x==m->x&&d->y==m->y);if(d->hits==2){doubles++;assert(!d->critical);}if(d->critical)crits++;}assert(doubles>700&&doubles<1300&&crits>0);
 assert(combat_change_job(&g,5));g.joblevel=20;g.skillPoints=19;assert(skill_learn(&g,17));inventory_add(&g,8,1);inventory_action(&g,8);m->hp=100000;m->x=g.x+40;g.target=0;ready(&g);assert(skill_cast(&g,17,0,0));DamageEvent*d=&g.damage[(g.damageNext-1)%DAMAGE_EVENTS];assert(d->hits==2&&!d->critical&&d->value==100000-m->hp);SavedCharacter s;save_capture(&s,&g,1);assert(save_valid(&s));unsigned char raw[SAVE_BYTES];save_encode(raw,&s);assert(save_decode(&s,raw)==1);Combat h;save_restore(&h,&s,1500,1500,NULL,NULL);assert(h.damageNext==0&&h.jobId==5&&h.ranks[13]==1);puts("PASS bounded actual-damage events, Double Attack and Strafe multi-hits, normal-attack crits, HP consistency, Save10 unchanged and transient event reset");}
